import re

_UNITS = {
    "s": 1, "sec": 1, "secs": 1, "second": 1, "seconds": 1,
    "m": 60, "min": 60, "mins": 60, "minute": 60, "minutes": 60,
    "h": 3600, "hr": 3600, "hrs": 3600, "hour": 3600, "hours": 3600,
    "d": 86400, "day": 86400, "days": 86400,
    "w": 604800, "wk": 604800, "wks": 604800, "week": 604800, "weeks": 604800,
}

_NUM = r"\d+(?:\.\d+)?|\.\d+"
_ISO = re.compile(
    r"P(?:(?P<w>%s)W)?(?:(?P<d>%s)D)?(?:T(?:(?P<h>%s)H)?(?:(?P<m>%s)M)?(?:(?P<s>%s)S)?)?"
    % ((_NUM,) * 5)
)
_COMPONENT = re.compile(r"\s*(%s)\s*([a-zA-Z]+)\s*" % _NUM)


def _round(x: float) -> int:
    return int(x + 0.5)


def parse_duration(text: str) -> int:
    """Return the duration described by `text` in whole seconds. See README.md."""
    if not isinstance(text, str):
        raise ValueError("duration must be a string")
    s = text.strip()
    if not s:
        raise ValueError("empty duration")

    if re.fullmatch(r"\d+", s):
        return int(s)

    # ISO 8601
    if s[:1].upper() == "P":
        m = _ISO.fullmatch(s.upper())
        if not m or s.upper() in ("P", "PT") or s.upper().endswith("T"):
            raise ValueError(f"invalid ISO duration: {text!r}")
        if not any(m.group(k) for k in "wdhms"):
            raise ValueError(f"invalid ISO duration: {text!r}")
        mult = {"w": 604800, "d": 86400, "h": 3600, "m": 60, "s": 1}
        return _round(sum(float(m.group(k)) * v for k, v in mult.items() if m.group(k)))

    # Clock notation
    if ":" in s:
        parts = s.split(":")
        if len(parts) not in (2, 3):
            raise ValueError(f"invalid clock duration: {text!r}")
        if not all(re.fullmatch(r"\d+", p) for p in parts[:-1]) or not re.fullmatch(_NUM, parts[-1]):
            raise ValueError(f"invalid clock duration: {text!r}")
        vals = [float(p) for p in parts]
        if len(vals) == 2:
            vals = [0.0] + vals
        h, mi, se = vals
        return _round(h * 3600 + mi * 60 + se)

    # Unit components
    pos = 0
    total = 0.0
    count = 0
    while pos < len(s):
        m = _COMPONENT.match(s, pos)
        if not m or m.end() == pos:
            raise ValueError(f"invalid duration: {text!r}")
        unit = m.group(2).lower()
        if unit not in _UNITS:
            raise ValueError(f"unknown unit {m.group(2)!r} in {text!r}")
        total += float(m.group(1)) * _UNITS[unit]
        count += 1
        pos = m.end()
    if count == 0:
        raise ValueError(f"invalid duration: {text!r}")
    return _round(total)

